// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, uint8 callerSeed) public {
        vm.assume(amount > 0);
        vm.assume(callerSeed > 0);
        Receiver receiver = new Receiver();
        vm.deal(address(receiver), amount);
        vm.prank(address(receiver));
        c.addToBalance{value: amount}();
        uint256 balanceBefore = address(receiver).balance;
        vm.prank(address(receiver));
        c.withdrawBalance();
        uint256 received = address(receiver).balance - balanceBefore;
        assertTrue(c.getBalance(address(receiver)) == 0 && received == amount);
    }
}

contract Receiver {
    receive() external payable {}
}
